# Parse
def parse_grid(text, sep=' '):
    grid = []
    for line in text.strip().split('\n'):
        row = [int(x) for x in line.split(sep)]
        grid.append(row)
    return grid

inp = parse_grid(demo1_input)
out = parse_grid(demo1_output)

R, C = len(inp), len(inp[0])
print(f"Demo 1 grid: {R} rows x {C} cols")

# Find where values changed from 3 to something else
changed = []
unchanged_3 = []
for r in range(R):
    for c in range(C):
        val = inp[r][c]
        if val == 3:
            if out[r][c] != 3:
                changed.append((r,c,f"{val}->{out[r][c]}"))
            else:
                unchanged_3.append((r,c))

print(f"\nCells that changed from 3: {len(changed)} total")
print(f"  Sample: {changed}")

# Check all 4 edges
touches_top = [c for c in range(C) if inp[0][c]==3]
touches_bottom = [c for c in range(C) if inp[R-1][c]==3]
touches_left = [r for r in range(R) if inp[r][0]==3]
touches_right = [r for r in range(R) if inp[r][C-1]==3]

print(f"\n3s touching edges:")
print(f"  Top row (row 0): cols {sorted(touches_top)}")
print(f"  Bottom row (row {R-1}): cols {sorted(touches_bottom)}")
print(f"  Left col (col 0): rows {sorted(touches_left)}")
print(f"  Right col (col {C-1}): rows {sorted(touches_right)}")

# Check changes at edges
print("\n=== Changes at each edge ===")
for r in touches_left:
    if out[r][0] != 3:
        print(f"Left edge row {r}: 3->{out[r][0]}")
for r in touches_right:
    if out[r][C-1] != 3:
        print(f"Right edge row {r}: {inp[r][C-1]}->{out[r][C-1]}")
for c in touches_top:
    if out[0][c] != 3:
        print(f"Top edge col {c}: 3->{out[0][c]}")
for c in touches_bottom:
    if out[R-1][c] != 3:
        print(f"Bottom edge col {c}: {inp[R-1][c]}->{out[R-1][c]}")

